// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract TransactionManager {
    // 交易结构体
    struct Transaction {
        uint256 id;
        string fromUserId;
        string toUserId;
        uint256 amount;
        uint256 interest;
        uint256 totalRepay;
        uint256 timestamp;
        string transactionType;
        string status;
        uint256 dueDate;
        string hash;
    }

    // 交易事件
    event TransactionCreated(
        uint256 indexed id,
        string fromUserId,
        string toUserId,
        uint256 amount,
        string transactionType
    );

    event TransactionUpdated(
        uint256 indexed id,
        string status
    );

    // 交易存储
    mapping(uint256 => Transaction) public transactions;
    uint256 public nextTransactionId;

    // 创建交易
    function createTransaction(
        string memory fromUserId,
        string memory toUserId,
        uint256 amount,
        uint256 interest,
        uint256 totalRepay,
        string memory transactionType,
        uint256 dueDate,
        string memory hash
    ) public returns (uint256) {
        uint256 transactionId = nextTransactionId;
        transactions[transactionId] = Transaction({
            id: transactionId,
            fromUserId: fromUserId,
            toUserId: toUserId,
            amount: amount,
            interest: interest,
            totalRepay: totalRepay,
            timestamp: block.timestamp,
            transactionType: transactionType,
            status: "pending",
            dueDate: dueDate,
            hash: hash
        });
        nextTransactionId++;

        emit TransactionCreated(
            transactionId,
            fromUserId,
            toUserId,
            amount,
            transactionType
        );

        return transactionId;
    }

    // 更新交易状态
    function updateTransactionStatus(uint256 transactionId, string memory newStatus) public {
        require(transactionId < nextTransactionId, "Transaction does not exist");
        transactions[transactionId].status = newStatus;

        emit TransactionUpdated(transactionId, newStatus);
    }

    // 获取交易
    function getTransaction(uint256 transactionId) public view returns (Transaction memory) {
        require(transactionId < nextTransactionId, "Transaction does not exist");
        return transactions[transactionId];
    }

    // 获取交易数量
    function getTransactionCount() public view returns (uint256) {
        return nextTransactionId;
    }
}

